using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketModelTrainer>();

var app = builder.Build();

// Train the model at startup and register the pooled prediction engine
var trainer = app.Services.GetRequiredService<TicketModelTrainer>();
trainer.TrainAndSave();

builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(trainer.ModelPath);

// Rebuild the service provider so PredictionEnginePool is available
app = builder.Build();
app.MapControllers();
app.Run();

