using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public sealed class TicketModelTrainer
{
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly ILogger<TicketModelTrainer> _logger;

    // Stored after training so the prediction endpoint can map scores to label names
    public string[] CategoryLabels { get; private set; } = [];

    public TicketModelTrainer(IWebHostEnvironment env, ILogger<TicketModelTrainer> logger)
    {
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "ticket_model.zip");
        _logger = logger;
    }

    public void TrainAndSave()
    {
        var mlContext = new MLContext(seed: 42);

        IDataView data = mlContext.Data.LoadFromTextFile<TicketData>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // With a small dataset we train on all rows and cross-validate for metrics
        var pipeline = mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject))
            .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category)))
            .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Starting model training...");

        // Cross-validate to get metrics (better than a single split on tiny data)
        var cvResults = mlContext.MulticlassClassification.CrossValidate(data, pipeline, numberOfFolds: 3);

        foreach (var (fold, result) in cvResults.Select((r, i) => (i + 1, r)))
        {
            _logger.LogInformation(
                "Fold {Fold}: MicroAccuracy={Micro:F4}, MacroAccuracy={Macro:F4}, LogLoss={LogLoss:F4}",
                fold, result.Metrics.MicroAccuracy, result.Metrics.MacroAccuracy, result.Metrics.LogLoss);
        }

        var avgMicro = cvResults.Average(r => r.Metrics.MicroAccuracy);
        var avgMacro = cvResults.Average(r => r.Metrics.MacroAccuracy);
        var avgLogLoss = cvResults.Average(r => r.Metrics.LogLoss);

        _logger.LogInformation(
            "Average metrics: MicroAccuracy={Micro:F4}, MacroAccuracy={Macro:F4}, LogLoss={LogLoss:F4}",
            avgMicro, avgMacro, avgLogLoss);

        // Train final model on full dataset
        var model = pipeline.Fit(data);

        // Extract label names for score mapping
        var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
        model.LastTransformer.GetOutputSchema(model.GetOutputSchema(data.Schema))["Score"]
            .Annotations.GetValue("SlotNames", ref labelBuffer);
        CategoryLabels = labelBuffer.DenseValues().Select(v => v.ToString()).ToArray();

        mlContext.Model.Save(model, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);
    }

    public string ModelPath => _modelPath;
}

